<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Food extends Model { protected $table='foods'; protected $fillable=['category_id','name','slug','description','price','quantity','low_stock_threshold','image','is_available','is_featured','is_best_seller']; protected $casts=['price'=>'decimal:2','is_available'=>'boolean','is_featured'=>'boolean','is_best_seller'=>'boolean']; public function category(){return $this->belongsTo(Category::class);} public function transactions(){return $this->hasMany(InventoryTransaction::class);} }
